/** Review world: six actual villages in ordinary terrain, complete ring and a verified full lap. */
final class RailRingDemo {
 static final List<BlockPos> villages=new ArrayList<>();static final List<RailwayNetwork.Station> stations=new ArrayList<>();static RailwayNetwork.Line line;static RailVehicleEntity a,b;static int stage,probe,ticks,stalled,forest;static double scan;static boolean done;static net.minecraft.server.network.ServerPlayerEntity observer;
 static void log(String s,Object...args){org.slf4j.LoggerFactory.getLogger("rail-ring-demo").info(s,args);}
 static RailwayNetwork.Station station(ServerWorld w,BlockPos village,Direction facing){RailwayNetwork.Station best=null;int score=Integer.MAX_VALUE;
  for(int i=0;i<16;i++){int side=(i%2==0?1:-1)*(256+(i/4)*32),ahead=-32+(i/2%2)*48;var base=village.offset(facing.rotateYCounterclockwise(),side).offset(facing,ahead);var candidate=new RailwayNetwork.Station(village.asLong(),base,facing.getHorizontalQuarterTurns(),0);var heights=new ArrayList<Integer>();
   for(int x:new int[]{0,21,42})for(int z:new int[]{0,32,64}){var p=candidate.pos(x,0,z);w.getChunk(p);heights.add(RailTerrain.ground(w,p.getX(),p.getZ()));}
   Collections.sort(heights);if(heights.getFirst()<=w.getSeaLevel())continue;int range=heights.getLast()-heights.getFirst();if(range<score){score=range;best=new RailwayNetwork.Station(village.asLong(),base.withY(heights.get(4)-1),facing.getHorizontalQuarterTurns(),0);}if(range<=4)break;
  }if(best==null)throw new IllegalStateException("No dry station site at "+village);return best;
 }
 static void placeStation(ServerWorld w,RailwayNetwork.Station station){var map=RailwayNetwork.building(w,station,"railway_station");for(var e:map.entrySet()){w.getChunk(e.getKey());w.setBlockState(e.getKey(),VillageConnections.connected(w,e.getKey(),e.getValue()),Block.NOTIFY_LISTENERS);}
  for(int x=0;x<43;x++)for(int z=0;z<65;z++)for(int down=1;down<=40;down++){var p=station.pos(x,-down,z);if(w.getBlockState(p).isSolidBlock(w,p))break;w.setBlockState(p,down<=2?Blocks.STONE_BRICKS.getDefaultState():Blocks.DIRT.getDefaultState(),Block.NOTIFY_LISTENERS);}
  var village=BlockPos.fromLong(station.village);var start=new Vec3d(village.getX(),0,village.getZ());var end=Vec3d.of(station.pos(12,0,-4));double length=Math.hypot(end.x-start.x,end.z-start.z);int previousY=Integer.MIN_VALUE;
  for(int i=0;i<=length;i++){var p=start.lerp(end,i/length);w.getChunk((int)p.x>>4,(int)p.z>>4);int y=RailTerrain.ground(w,(int)p.x,(int)p.z)-1;if(previousY!=Integer.MIN_VALUE)y=Math.clamp(y,previousY-1,previousY+1);if(i>=length-3)y=station.origin.getY();previousY=y;
   for(int side=-1;side<=1;side++){var q=new BlockPos((int)p.x,y,(int)p.z).offset(station.side(),side);w.getChunk(q);if(w.getBlockState(q).hasBlockEntity())continue;w.setBlockState(q,Blocks.STONE_BRICKS.getDefaultState(),Block.NOTIFY_LISTENERS);for(int h=1;h<=3;h++){var old=w.getBlockState(q.up(h));if(!old.hasBlockEntity()&&(VillageProjects.terrain(old)||old.isIn(net.minecraft.registry.tag.BlockTags.LOGS)||old.isIn(net.minecraft.registry.tag.BlockTags.LEAVES)||old.isReplaceable()))w.setBlockState(q.up(h),Blocks.AIR.getDefaultState(),Block.NOTIFY_LISTENERS);}}
  }
 }
 static void seedPassengers(ServerWorld w){for(var train:RailVehicleEntity.nearby(w,new Box(-10000,-64,-10000,10000,400,10000)))if(train.kind()==1){int count=0;for(var point:train.seats()){if(count>=2)break;if(!RailBoarding.free(w,train,point))continue;var person=EntityType.VILLAGER.create(w,SpawnReason.EVENT);var seat=RailContent.SEAT.create(w,SpawnReason.EVENT);if(person==null||seat==null)continue;seat.owner=train.getUuid();seat.local=point;seat.setPosition(RailGeometry.rotate(point,train.getYaw()).add(train.getEntityPos()));w.spawnEntity(seat);person.setPosition(seat.getEntityPos());person.setPersistent();person.addCommandTag("halloween_train_passenger");w.spawnEntity(person);person.startRiding(seat,true,false);seat.syncToTrain();count++;}}}
 static void register(){if(!Boolean.getBoolean("halloween.railRingDemo"))return;ServerTickEvents.END_SERVER_TICK.register(server->{if(done||server.getTicks()<40)return;var w=server.getOverworld();try{
  RailDeferred.tick(w);if(stage==0){server.getTickManager().setTickRate(1000);if(villages.isEmpty()&&WorldSettlements.get(w).cities.size()>=6)for(var c:WorldSettlements.get(w).cities.subList(0,6))villages.add(c.pos);var first=villages.isEmpty()?w.locateStructure(StructureTags.VILLAGE,BlockPos.ORIGIN,32,false):villages.getFirst();if(first==null)throw new AssertionError("first village");if(villages.isEmpty())villages.add(first);
   if(villages.size()<6){double angle=probe*Math.PI/4;int radius=probe==0?900:1100+(probe/8)*600;probe++;var p=w.locateStructure(StructureTags.VILLAGE,first.add((int)(Math.cos(angle)*radius),0,(int)(Math.sin(angle)*radius)),24,false);if(p!=null&&villages.stream().noneMatch(v->VillageEras.horizontal(v,p)<450*450))villages.add(p);if(probe>40)throw new AssertionError("six distinct villages not found");return;}
   double cx=villages.stream().mapToInt(BlockPos::getX).average().orElse(0),cz=villages.stream().mapToInt(BlockPos::getZ).average().orElse(0);villages.sort(Comparator.comparingDouble(p->Math.atan2(p.getZ()-cz,p.getX()-cx)));Collections.rotate(villages,-villages.indexOf(first));stage=1;log("SIX VILLAGES {}",villages);if(RailwayNetwork.get(w).stations.size()>=6){var network=RailwayNetwork.get(w);boolean safe=network.stations.stream().allMatch(st->{var city=BlockPos.fromLong(st.village);var side=st.side();return Math.abs((st.origin.getX()-city.getX())*side.getOffsetX()+(st.origin.getZ()-city.getZ())*side.getOffsetZ())>=224;});
    if(safe){for(var p:villages){var existing=network.stations.stream().filter(st->st.village==p.asLong()).findFirst().orElse(null);if(existing!=null)stations.add(existing);}if(stations.size()==6){line=network.lines.isEmpty()?null:network.lines.getFirst();stage=line==null?4:2;if(line!=null&&line.spawned){stage=5;for(var e:w.iterateEntities())if(e instanceof RailVehicleEntity t&&t.kind()==0&&t.visits>0){if(a==null)a=t;else if(b==null)b=t;}if(a!=null&&b!=null){var engineChunk=new ChunkPos(a.getBlockPos());for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)w.setChunkForced(engineChunk.x+dx,engineChunk.z+dz,true);stage=3;}}log("RESUME safe stations and route section {}",line==null?0:line.next);}}
    else{for(var old:List.copyOf(network.stations))for(var entry:RailwayNetwork.building(w,old,"railway_station").entrySet()){var p=entry.getKey();w.getChunk(p);if(!entry.getValue().isAir()&&w.getBlockState(p).isOf(entry.getValue().getBlock()))w.setBlockState(p,Blocks.AIR.getDefaultState(),Block.NOTIFY_LISTENERS);}for(var old:network.lines)for(double d=0;d<old.next*16;d+=4)for(double lane:new double[]{-4,4}){var p=BlockPos.ofFloored(old.path.at(d,lane));if(w.isChunkLoaded(new ChunkPos(p).toLong())&&w.getBlockState(p).isOf(RailContent.TRACK))w.setBlockState(p,Blocks.AIR.getDefaultState(),Block.NOTIFY_LISTENERS);}network.stations.clear();network.lines.clear();network.markDirty();log("Relocating stations alongside villages to keep inbound tracks clear of homes");}
   }

  }else if(stage==1){int i=stations.size();var prev=villages.get(Math.floorMod(i-1,6));var next=villages.get((i+1)%6);var facing=Direction.getFacing(next.getX()-prev.getX(),0,next.getZ()-prev.getZ());var s=station(w,villages.get(i),facing);stations.add(s);RailwayNetwork.get(w).stations.add(s);RailwayNetwork.get(w).markDirty();WorldSettlements.discover(w,villages.get(i));placeStation(w,s);if(i==0)RailVillageDemo.placeBuilding(w,RailwayNetwork.foundry(s),"rail_foundry");log("STATION {} {}",i+1,s.origin);
   if(stations.size()==6)stage=4;
  }else if(stage==4){line=RailwayNetwork.connectRing(w,stations);if(line!=null){stage=2;log("ROUTE {} metres, {} cubic controls",Math.round(line.path.length),line.controls.size());}
  }else if(stage==5){var first=stations.getFirst();for(int k=0;k<8&&scan<line.path.length;k++,scan+=8)for(double lane:new double[]{-4,4})w.getChunk(BlockPos.ofFloored(line.path.at(scan,lane)));w.getChunk(BlockPos.ofFloored(first.center(48)));w.getChunk(BlockPos.ofFloored(first.center(16)));if(observer==null){observer=new net.minecraft.server.network.ServerPlayerEntity(server,w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"RouteObserver"),net.minecraft.network.packet.c2s.common.SyncedClientOptions.createDefault());observer.networkHandler=new net.minecraft.server.network.ServerPlayNetworkHandler(server,new net.minecraft.network.ClientConnection(net.minecraft.network.NetworkSide.SERVERBOUND),observer,net.minecraft.server.network.ConnectedClientData.createDefault(observer.getGameProfile(),false));observer.changeGameMode(net.minecraft.world.GameMode.SPECTATOR);observer.setPosition(first.center(32).add(0,20,0));}
   var ticket=new ChunkPos(BlockPos.ofFloored(first.center(32)));for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++)w.setChunkForced(ticket.x+dx,ticket.z+dz,true);VillageProjects.keepLoaded(w,BlockPos.ofFloored(first.center(48)));VillageProjects.keepLoaded(w,BlockPos.ofFloored(first.center(16)));for(var e:w.iterateEntities())if(e instanceof RailVehicleEntity t&&t.kind()==0&&t.visits>0){if(a==null)a=t;else if(t!=a&&b==null)b=t;}if(a!=null&&b!=null){var engineChunk=new ChunkPos(a.getBlockPos());for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)w.setChunkForced(engineChunk.x+dx,engineChunk.z+dz,true);stage=3;}
  }else if(stage==2){
   if(observer==null){observer=new net.minecraft.server.network.ServerPlayerEntity(server,w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"RouteObserver"),net.minecraft.network.packet.c2s.common.SyncedClientOptions.createDefault());observer.networkHandler=new net.minecraft.server.network.ServerPlayNetworkHandler(server,new net.minecraft.network.ClientConnection(net.minecraft.network.NetworkSide.SERVERBOUND),observer,net.minecraft.server.network.ConnectedClientData.createDefault(observer.getGameProfile(),false));observer.changeGameMode(net.minecraft.world.GameMode.SPECTATOR);}
   line=RailwayNetwork.get(w).lines.getFirst();observer.setPosition(line.path.center(line.next*16).add(0,20,0));
   int before=line.next;for(int budget=0;budget<4;budget++){RailTerrain.place(w,line,line.next);if(!RailwayNetwork.get(w).lines.contains(line)){line=RailwayNetwork.get(w).lines.getFirst();break;}if(line.next==(int)Math.ceil(line.path.length/16))break;}if(line.next==before){if(++stalled%2000==0)log("Waiting for track segment {}: {}",line.next,RailTerrain.lastIssue);if(stalled>200000)throw new AssertionError("route obstructed at "+line.next+" "+line.path.center(line.next*16));}else stalled=0;
   if(line.next%64==0&&line.next!=before)log("TRACK {}/{}",line.next,(int)Math.ceil(line.path.length/16));
   if(line.next>=(int)Math.ceil(line.path.length/16)){line.spawned=true;RailwayNetwork.get(w).markDirty();var trains=RailwayNetwork.startLine(w,line);a=trains.get(0);b=trains.get(3);a.dwell=600;b.dwell=600;
    for(var train:trains)if(train.kind()==1)for(int n=0;n<3;n++){var npc=EntityType.VILLAGER.create(w,SpawnReason.EVENT);if(npc==null)continue;npc.setPersistent();npc.setPosition(train.getEntityPos().add(RailGeometry.rotate(new Vec3d(-3,2,5.5-n*.6),train.getYaw())));w.spawnEntity(npc);RailBoarding.invite(w,train,npc);}
    stage=3;log("READY two opposite trains, real boarding passengers, six stations");}
  }else if(stage==3){if(observer!=null)observer.setPosition(a.getEntityPos().add(0,20,0));ticks++;if(ticks%5000==0)log("DRIVE tick={} stops={}/{} speed={}/{} distance={}/{}",ticks,a.visits,b.visits,a.speed,b.speed,a.distance,b.distance);RailStationSafety.tick(w);if(a.direction!=1||b.direction!=1)throw new AssertionError("engine reversed on ring");
   if(a.visits>=7&&b.visits>=7){log("PASS both engines completed six stations and returned; stops={}/{} elapsed={} ticks",a.visits,b.visits,ticks);for(var root:List.of(a,b)){var station=stations.getFirst();var tangent=root.route().tangent(root.route().closest(station.center(32)));boolean reverse=tangent.dotProduct(new Vec3d(station.forward().getOffsetX(),0,station.forward().getOffsetZ()))<0;root.distance=root.route().closest(station.center(reverse?16:48));}a.speed=0;b.speed=0;a.dwell=Integer.MAX_VALUE;b.dwell=Integer.MAX_VALUE;a.setStops(a.stationStops);b.setStops(b.stationStops);
    for(var t:RailVehicleEntity.nearby(w,new Box(-10000,-64,-10000,10000,400,10000)))if(t.kind()==0)t.tick();for(var t:RailVehicleEntity.nearby(w,new Box(-10000,-64,-10000,10000,400,10000)))if(t.kind()==1)t.tick();var state=WorldSettlements.get(w);state.epoch=w.getTime()-8*24000;state.markDirty();server.getTickManager().setTickRate(20);w.setTimeOfDay(6000);stage=6;server.getTickManager().setTickRate(1000);}else if(ticks>90000)throw new AssertionError("ring stalled visits="+a.visits+"/"+b.visits);}
  else if(stage==6){for(int i=0;i<2&&forest*16<line.path.length;i++,forest++)RailForest.edge(w,line.path,forest*16);if(forest%64==0)log("TAIGA {}/{}",forest,(int)Math.ceil(line.path.length/16));if(forest*16>=line.path.length){log("PASS: tall green taiga corridor, no snow beside the railway");a.dwell=600;b.dwell=600;seedPassengers(w);server.getTickManager().setTickRate(20);w.setWeather(0,120000,false,false);done=true;server.stop(false);}}
 }catch(Throwable e){done=true;org.slf4j.LoggerFactory.getLogger("rail-ring-demo").error("FAIL",e);server.stop(false);}});}
}
